import Foundation
/// Certificates for verification tests, generated with OpenSSL (P-256, valid 2026-11-14 … 2036-11-11):
/// a private CA; a CA-signed leaf with SAN DNS:db.example.test, DNS:*.pg.example.test, IP:127.0.0.1, IP:::1 and
/// CN ignored.example.test; a CA-signed CN-only leaf (cnonly.example.test, no SAN/EKU — the PostgreSQL docs
/// recipe); and a leaf with the same SAN signed by an unrelated CA. All leaves are valid for 3650 days, which
/// Apple's TLS server policy rejects.
enum TestCertificates {
    static let ca = ""
    static let san = ""
    static let cn = ""
    static let rogue = ""
}
